    53	/**
    54	 * The owner of the IOU report is the account who is owed money and the manager is the one who owes money!
    55	 * In case the owner/manager swap, we need to update the owner of the IOU report and the report total, since it is always positive.
    56	 * For example: if user1 owes user2 $10, then we have: {ownerAccountID: user2, managerID: user1, total: $10 (a positive amount, owed to user2)}
    57	 * If user1 requests $17 from user2, then we have: {ownerAccountID: user1, managerID: user2, total: $7 (still a positive amount, but now owed to user1)}
    58	 *
    59	 * @param isDeleting - whether the user is deleting the expense
    60	 * @param isUpdating - whether the user is updating the expense
    61	 */
    62	function updateIOUOwnerAndTotal<TReport extends OnyxInputOrEntry<Report>>(
    63	    iouReport: TReport,
    64	    actorAccountID: number,
    65	    amount: number,
    66	    currency: string,
    67	    isDeleting = false,
    68	    isUpdating = false,
    69	): TReport {
    70	    // For the update case, we have calculated the diff amount in the calculateDiffAmount function so there is no need to compare currencies here
    71	    if ((currency !== iouReport?.currency && !isUpdating) || !iouReport) {
    72	        return iouReport;
    73	    }
    74	
    75	    // Make a copy so we don't mutate the original object
    76	    const iouReportUpdate = {...iouReport};
    77	
    78	    // Let us ensure a valid value before updating the total amount.
    79	    iouReportUpdate.total = iouReportUpdate.total ?? 0;
    80	
    81	    if (actorAccountID === iouReport.ownerAccountID) {
    82	        iouReportUpdate.total += isDeleting ? -amount : amount;
    83	    } else {
    84	        iouReportUpdate.total += isDeleting ? amount : -amount;
    85	    }
    86	
    87	    if (iouReportUpdate.total < 0) {
    88	        // The total sign has changed and hence we need to flip the manager and owner of the report.
    89	        iouReportUpdate.ownerAccountID = iouReport.managerID;
    90	        iouReportUpdate.managerID = iouReport.ownerAccountID;
    91	        iouReportUpdate.total = -iouReportUpdate.total;
    92	    }
    93	
    94	    return iouReportUpdate;
    95	}
